create_external_database.code:
final response = await client.externalDatabases.createExternalDatabase({
  'external_database': {
    'name': 'acmedb',
    'tables': [
      {
        'table_name': 'contacts',
        'fields': ['company'],
        'records': [
          {
            'record': [
              {'field': 'company', 'value': 'Acme Pty Ltd'},
            ],
          },
        ],
      },
    ],
  },
});
print(response.map);

