    .updateExternalDatabaseUpdateRecords('acmedb', {
      'table_name': 'contacts',
      'update_fields': [
        {'field_name': 'company', 'field_value': 'Acme Group'},
      ],
      'where_condition': {
        'field_name': 'company',
